  // Automatically capture the current user prompt when available (default: true). Set false for SDD artifacts or automated saves.
  capture_prompt?: boolean;
  // Structured content using **What**, **Why**, **Where**, **Learned** format. Required unless observation alias is provided.
  content?: string;
  // Backward-compatible alias for content. Prefer content for new clients.
  observation?: string;
  // Optional explicit project for this memory. Accepted only when backed by known context (existing project, matching session, repo config, or ambiguous-project recovery); invalid or unbacked names fail loudly.
  project?: string;
  // Must be user_selected_after_ambiguous_project, and only after the user explicitly chose one of available_projects from an ambiguous_project error.
  project_choice_reason?: string;
  // Short-lived token returned by an ambiguous_project error. Required with project_choice_reason=user_selected_after_ambiguous_project.
  recovery_token?: string;
  // Scope for this observation: project (default) or personal
  scope?: string;
  // Session ID to associate with (default: manual-save-{project})
  session_id?: string;
  // Short, searchable title (e.g. 'JWT auth middleware', 'Fixed N+1 query')
  title: string;
  // Optional topic identifier for upserts (e.g. architecture/auth-model). Reuses and updates the latest observation in same project+scope.
  topic_key?: string;
  // Category: decision, architecture, bugfix, pattern, config, discovery, learning (default: manual)
  type?: string;
}): Promise<CallToolResult>; };
```"}

