from html.parser import HTMLParser
from pathlib import Path
from collections import defaultdict

TARGETS={'panel-resumen-ejecutivo','panel-competencia','panel-red-facebook','panel-red-instagram','panel-red-tiktok','panel-plan-optimizacion'}
class P(HTMLParser):
  def __init__(self):
    super().__init__(); self.stack=[]; self.current=None; self.depth=0; self.data=defaultdict(lambda: defaultdict(list)); self.text_stack=[]
  def handle_starttag(self, tag, attrs):
    a=dict(attrs); self.depth+=1
    if self.current is None and a.get('id') in TARGETS:
      self.current=a['id']; self.panel_depth=self.depth
    if self.current:
      cls=a.get('class','').split()
      if tag in ('canvas','svg','table','iframe','img'):
        self.data[self.current][tag].append(a.get('id') or a.get('class') or tag)
      if tag in ('h1','h2','h3','h4') or any(x in cls for x in ('section-title','card-title','stat-label','section-eyebrow')):
        self.text_stack.append((tag,self.depth,[]))
      if any(x in cls for x in ('editable','insights-list','recommendations-list','post-card','reel-card')):
        self.data[self.current]['families'].append('/'.join(cls))
  def handle_data(self,d):
    if self.current and self.text_stack: self.text_stack[-1][2].append(d)
  def handle_endtag(self,tag):
    if self.current and self.text_stack and self.text_stack[-1][0]==tag:
      _,_,parts=self.text_stack.pop(); t=' '.join(' '.join(parts).split())
      if t: self.data[self.current]['headings'].append(t)
    if self.current and self.depth==self.panel_depth:
      self.current=None
    self.depth-=1
p=P(); p.feed(Path('/Users/inhaus/Documents/GitHub/Dashboards/Nutri/nutri_normal/index.html').read_text(errors='ignore'))
for k in TARGETS:
  print('\n##',k)
  d=p.data[k]
  print('counts', {x:len(d[x]) for x in ('canvas','svg','table','iframe','img','families')})
  print('charts',d['canvas'][:20])
  print('headings')
  for h in d['headings'][:60]: print('-',h[:180])
